/* Own MIT. Field lookup by name for the single DBF workarea (hrdbf_app.c).
 * Compiled on its own, with hbc's internal SysV ABI, for every target: it
 * only reads hrdbf_app_state (hrdbf_file starts with its hrdbf_area), so
 * the per-OS DBF blobs stay untouched. Generated by
 * tests/generate_dbf_fieldpos_asm.py into generated/hrdbf_fieldpos.s. */
#include "hrdbf.h"

extern hrdbf_area hrdbf_app_state;

static unsigned char up(unsigned char c) { return c >= 'a' && c <= 'z' ? (unsigned char)(c - 32) : c; }

/* -1: no workarea is open; 0: no field with that name; else the 1-based
 * field ordinal. Names compare case-insensitively, like Harbour's field
 * symbols; a DBF name ends at its first NUL (at most 10 bytes). */
int64_t hrdbf_app_fieldpos(const unsigned char *name, uint64_t len) {
  const hrdbf_area *a = &hrdbf_app_state;
  if (!a->open) return -1;
  for (unsigned f = 0; f < a->nfields; f++) {
    const unsigned char *fn = a->fields[f].name;
    uint64_t k = 0;
    while (k < 11 && fn[k]) k++;
    if (k != len) continue;
    uint64_t j = 0;
    while (j < k && up(fn[j]) == up(name[j])) j++;
    if (j == k) return (int64_t)f + 1;
  }
  return 0;
}
